window.RP_SESSION={"id":"S-7979586cb86b","messages":[{"id":"RP-0049307","time":"2026-02-18T23:44:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"reviewed","type":"dialogue","body":"\" 벌써 자정이 다 되어가는군. 다들 오늘 하루는 잘 보내셨나? 내 주점은 슬슬 문 닫을 시간일세. 하루동안 자신이 원하는 바를 이룬 사람도 있겠고, 안타깝게도 원하지 않는 시간을 보내거나 힘들게 지내온 사람들도 있겠지. 그래도 괜찮네! 하루의 마지막에는 웃어보게나. 내일은 내일의 해가 뜨고, 내일의 해가 뜨면 또 새로운 일들이 일어날 테니. 삶은 축복이라네. 모두 그 축복을 즐기길 바라지! 이 노인네는 이만 줄이겠네. \"\n\n주점의 팻말이 CLOSE로 뒤집힙니다. 주인은 자러 간 모양입니다...","characters":["P-324e65118d90"]},{"id":"RP-0049308","time":"2026-02-19T01:40:00+09:00","room":"RP","name":"메타 반응","profile":"존","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0049309","time":"2026-02-19T01:41:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
